formulas.expression:
/* 1: Opt-In Text - recipient Missing Mobile & SMS Opt Out */
IF(
AND({!buttons_contextual.value} = {!c_Send_Opt_In_Text}, {!var_recipientNumber} = "Error", {!var_recipientSMSOptOut} = true
),
"🚫Error. Unable to send Opt-In Text due to reason: Missing Customer Phone Number & Customer has Opted out from SMS",

/* 2: Opt-In Text - recipient Missing Mobile */
IF(
AND({!buttons_contextual.value} = {!c_Send_Opt_In_Text}, {!var_recipientNumber} = "Error"
),
"🚫Error. Unable to send Opt-In Text due to reason: Missing Customer Phone Number",

/* 3: Opt-In Text - recipient Opted out of SMS */
IF(
AND({!buttons_contextual.value} = {!c_Send_Opt_In_Text}, {!var_recipientSMSOptOut} = true),
"🚫Error. Unable to send Opt-In Text due to reason: Customer has Opted Out of SMS",

/* 4: Send DFP Email - recipient Missing Email & Email Opted Out */
IF(
AND({!buttons_contextual.value} = {!c_Send_DFP_Email}, {!var_recipientEmail} = "Error", {!var_recipientEmailOptOut} = true),
"🚫Error. Unable to send DFP Email due to reason: Missing Customer Email & Customer has Opted out from Email",

/* 5: Send DFP Email - recipient Missing Email */
IF(
AND({!buttons_contextual.value} = {!c_Send_DFP_Email}, {!var_recipientEmail} = "Error"),
"🚫Error. Unable to send DFP Email due to reason: Missing Customer Email",

/* 6: Send DFP Email - recipient Opted out of Email */
IF(
AND({!buttons_contextual.value} = {!c_Send_DFP_Email}, {!var_recipientEmailOptOut} = true),
"🚫Error. Unable to send DFP Email due to reason: Customer has Opted Out of Email",

/* 7: Send DFP Text - Missing Both Customer Mobile & Customer Opted Out */
IF(
AND({!buttons_contextual.value} = {!c_Send_DFP_Text}, {!var_recipientNumber} = "Error", {!var_recipientSMSOptOut} = true),
"🚫Error. Unable to send DFP Text due to reason: Missing Customer Phone Number & Customer has Opted Out from SMS",

/* 8: Send DFP Text - recipient Missing Mobile */
IF(
AND({!buttons_contextual.value} = {!c_Send_DFP_Text}, {!var_recipientNumber} = "Error"),
"🚫Error. Unable to send DFP Text due to reason: Missing Customer Phone Number",

/* 9: Send DFP Text - recipient Opted out of SMS */
IF(
AND({!buttons_contextual.value} = {!c_Send_DFP_Text}, {!var_recipientSMSOptOut} = true),
"🚫Error. Unable to send DFP Text due to reason: Customer has Opted Out of SMS",

/* 10: No issues — validation passed */
"Success"
)
)
)
)
)
)
)
)
)
